-- Coordinated cutover: stop app and worker before expanding StoreState.
-- Existing clinical identities/scopes are preserved. New activities start empty.
CREATE OR REPLACE FUNCTION cvg_runtime_entity_collections() RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT ARRAY['users','sessions','patients','encounters','admissions','services','reasonCodes',
  'requests','items','samples','procedures','schedules','results','resultVersions','notifications',
  'idempotency','attachments','departments','accessGroups','patientGrants','examDefinitions','hospitalServices',
  'hospitalTaskTypes','hospitalTasks','hospitalTaskDependencies','hospitalIntakes','savedPlannerViews']::text[]
$$;
CREATE UNIQUE INDEX cvg_hospital_task_type_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection='hospitalTaskTypes';
CREATE UNIQUE INDEX cvg_hospital_task_code_unique ON cvg_runtime_entities ((data->>'taskCode')) WHERE collection='hospitalTasks';
CREATE UNIQUE INDEX cvg_hospital_dependency_unique ON cvg_runtime_entities ((data->>'taskId'),(data->>'targetType'),(data->>'targetId'),(data->>'blocks')) WHERE collection='hospitalTaskDependencies' AND data->>'active'='true';
DO $$
