,"patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","patient.create","exam_definition.approve"]}'::jsonb;
 target_defaults jsonb := '{"ADMIN":["hospital_task_type.manage","access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage"],"MANAGER":["planner_view.share","hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.assignment.update","item.priority.update","item.plan.update","exam_definition.approve","access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.update","department.members.manage","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","service.catalog.manage","sla_policy.manage","reason_code.manage","user_role.manage","audit.view"],"VETERINARIAN":["hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.priority.update","exam_definition.approve","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"INPATIENT_TEAM":["hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.priority.update","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"LAB_TECH":["hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.assignment.update","item.plan.update","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge","item.reject"],"RADIOLOGY_TEAM":["hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.assignment.update","item.plan.update","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"ULTRASOUND_TEAM":["hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.assignment.update","item.plan.update","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"VIEWER":["planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect"],"SUPERADMIN":["hospital_task_type.manage","access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage","planner_view.share","hospital_task.create","hospital_task.update","hospital_task.execute","hospital_task.assign","hospital_task.priority.update","hospital_task.dependency.manage","hospital_intake.create","hospital_intake.triage","item.assignment.update","item.priority.update","item.plan.update","exam_definition.approve","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","patient.create"]}'::jsonb;
 affected_groups text[];
 group_count integer;
BEGIN
 SELECT version INTO current_version FROM cvg_runtime_state WHERE id=1 FOR UPDATE;
 IF current_version IS NOT NULL THEN
  INSERT INTO cvg_runtime_entities(collection,entity_key,position,data,written_version)
   SELECT 'hospitalTaskTypes',entry->>'id',ordinality,entry || jsonb_build_object('createdAt',timestamp_text,'updatedAt',timestamp_text),current_version+1
   FROM jsonb_array_elements('[{"id":"hospital-task-type-routine","code":"ROUTINE","name":"Rotina operacional","careContextRequired":false,"states":[{"code":"PENDING","label":"Pendente","phase":"PENDING"},{"code":"IN_PROGRESS","label":"Em execução","phase":"IN_PROGRESS"},{"code":"COMPLETED","label":"Concluída","phase":"COMPLETED"},{"code":"CANCELLED","label":"Cancelada","phase":"CANCELLED"}],"active":true,"version":1},{"id":"hospital-task-type-care","code":"CARE","name":"Cuidado assistencial","careContextRequired":true,"states":[{"code":"PENDING","label":"Pendente","phase":"PENDING"},{"code":"IN_PROGRESS","label":"Em execução","phase":"IN_PROGRESS"},{"code":"COMPLETED","label":"Concluída","phase":"COMPLETED"},{"code":"CANCELLED","label":"Cancelada","phase":"CANCELLED"}],"active":true,"version":1}]'::jsonb) WITH ORDINALITY AS defaults(entry,ordinality);
  -- A customized matrix retains every chosen restriction, including reduced system profiles.
  WITH changed AS (
   UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('permissions',target_defaults->(data->>'systemRole'),
    'version',(data->>'version')::integer+1,'updatedAt',timestamp_text),written_version=current_version+1
   WHERE collection='accessGroups' AND previous_defaults ? (data->>'systemRole')
    AND (data->'permissions') @> (previous_defaults->(data->>'systemRole'))
    AND (previous_defaults->(data->>'systemRole')) @> (data->'permissions')
   RETURNING entity_key
  ) SELECT array_agg(entity_key),count(*) INTO affected_groups,group_count FROM changed;
  UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('version',(data->>'version')::integer+1),written_version=current_version+1
   WHERE collection='users' AND data->>'accessGroupId'=ANY(affected_groups);
  UPDATE cvg_runtime_entities AS session SET data=session.data || jsonb_build_object('revokedAt',timestamp_text,'version',(session.data->>'version')::integer+1),written_version=current_version+1
   WHERE session.collection='sessions' AND NOT session.data ? 'revokedAt' AND EXISTS(SELECT 1 FROM cvg_runtime_entities AS target
    WHERE target.collection='users' AND target.data->>'id'=session.data->>'userId' AND target.data->>'accessGroupId'=ANY(affected_groups));
  UPDATE cvg_runtime_state SET state=cvg_runtime_state_header(state),version=current_version+1,updated_at=now() WHERE id=1;
  INSERT INTO audit_events(id,event_type,entity_type,entity_id,correlation_id,metadata,occurred_at)
   VALUES('audit-migration-023','HospitalPlannerTasksEnabled','SchemaMigration','023_hospital_tasks','corr-migration-023',
    jsonb_build_object('systemGroupsUpdated',group_count,'clinicalScopeChanged',false,'diagnosticHistoryChanged',false,'activitiesFabricated',false),CURRENT_TIMESTAMP);
 END IF;
END $$;
ALTER TABLE cvg_runtime_state ADD CONSTRAINT runtime_hospital_tasks_are_external CHECK(state->'hospitalTaskTypes'='[]'::jsonb AND state->'hospitalTasks'='[]'::jsonb AND state->'hospitalTaskDependencies'='[]'::jsonb AND state->'hospitalIntakes'='[]'::jsonb AND state->'savedPlannerViews'='[]'::jsonb);
UPDATE relational_schema_markers SET schema_version='023_hospital_tasks' WHERE marker_key='RELATIONAL_CLINICAL_CORE_EXPAND_V1';
